import{_ as e,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"How we Operate Ceph at Scale | Ceph Days NYC 2024","description":"","frontmatter":{"title":"How we Operate Ceph at Scale | Ceph Days NYC 2024","date":"2024-06-18T00:00:00.000Z","updated":"2024-06-19T00:00:00.000Z","tags":["Ceph","分布式存储","自动化","性能优化","监控与告警"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/How_we_Operate_Ceph_at_Scale_Ceph_Days_NYC_2024.md","filePath":"posts/2024/How_we_Operate_Ceph_at_Scale_Ceph_Days_NYC_2024.md","lastUpdated":1780459816000}'),r={name:"posts/2024/How_we_Operate_Ceph_at_Scale_Ceph_Days_NYC_2024.md"};function o(n,a,h,s,p,_){return l(),i("div",null,[...a[0]||(a[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-digitalocean-大规模运营-ceph-的实践" tabindex="-1">会议主题：DigitalOcean 大规模运营 Ceph 的实践 <a class="header-anchor" href="#会议主题-digitalocean-大规模运营-ceph-的实践" aria-label="Permalink to &quot;会议主题：DigitalOcean 大规模运营 Ceph 的实践&quot;">​</a></h4><h4 id="会议时间-具体日期" tabindex="-1">会议时间：[具体日期] <a class="header-anchor" href="#会议时间-具体日期" aria-label="Permalink to &quot;会议时间：[具体日期]&quot;">​</a></h4><h4 id="会议地点-具体地点" tabindex="-1">会议地点：[具体地点] <a class="header-anchor" href="#会议地点-具体地点" aria-label="Permalink to &quot;会议地点：[具体地点]&quot;">​</a></h4><h4 id="主讲人-matt-digitalocean-存储系统团队-加拿大东部" tabindex="-1">主讲人：Matt（DigitalOcean 存储系统团队，加拿大东部） <a class="header-anchor" href="#主讲人-matt-digitalocean-存储系统团队-加拿大东部" aria-label="Permalink to &quot;主讲人：Matt（DigitalOcean 存储系统团队，加拿大东部）&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>DigitalOcean 简介</strong></p><ul><li>DigitalOcean 是一家成立于2012年的云服务提供商，以简单性为核心理念，提供包括Spaces（Ceph支持的S3兼容对象存储）在内的多种服务。</li><li>DigitalOcean 在全球拥有多个数据中心，提供多样化的资源部署选择。</li></ul></li><li><p><strong>Ceph 在 DigitalOcean 的应用</strong></p><ul><li>DigitalOcean 大规模使用 Ceph 用于块存储和对象存储，支持Volumes和Spaces等服务。</li><li>统计数据：58个集群，包括47个生产集群，超过200PB的原始存储，最大集群超过12PB，28,000个OSDs，1,600台服务器运行Ceph。</li></ul></li><li><p><strong>自动化与配置管理</strong></p><ul><li>使用Chef进行核心操作系统配置管理，Ansible用于Ceph特定任务，如集群部署和节点扩充。</li><li>使用AWX作为开源的自托管解决方案，运行Ansible playbooks，确保团队共享故障模式、保密信息并记录运行历史。</li></ul></li><li><p><strong>集群操作与维护</strong></p><ul><li>自动化工具支持新集群部署、节点扩充、节点预检、安全重启、配置管理和Ceph升级。</li><li>使用PG Remapper进行集群扩容，优化了对象存储的恢复过程，减少了块存储的并发控制以适应工作负载的延迟敏感性。</li></ul></li><li><p><strong>性能监控与优化</strong></p><ul><li>使用自研工具Marigraph进行集群延迟测量，优化了OSD启动和PG peering过程，减少了延迟敏感应用的影响。</li><li>针对对象存储，优化了RGW与RocksDB的交互，通过设置OSD异步恢复最小成本和启用TTL压缩，显著提高了性能和稳定性。</li></ul></li><li><p><strong>监控与告警</strong></p><ul><li>使用Ceph Exporter和Store Exporter收集集群和硬件状态数据，监控网络可达性和硬件健康状况。</li><li>Marigraph工具持续运行合成负载，提供关键的延迟和IO性能指标，帮助识别和解决性能问题。</li></ul></li><li><p><strong>反思与未来展望</strong></p><ul><li>早期块存储和对象存储团队的分离导致集群管理和自动化配置的差异，增加了复杂性和维护难度。</li><li>建议未来更多地整合自动化工具，减少配置分散，提升集群的一致性和可管理性。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续优化自动化工具，特别是Ansible playbooks，以提升集群操作的效率和一致性。</li><li>加强监控系统的集成和告警策略，确保及时发现并解决潜在的性能和稳定性问题。</li><li>探索更多自动化服务的可能性，减少手动操作，提升团队的整体工作效率。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>招聘插件和Q&amp;A环节，讨论了团队扩张和技术细节问题。</li></ul><h4 id="备注" tabindex="-1">备注： <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注：&quot;">​</a></h4><ul><li>会议内容涉及大量技术细节和特定工具的使用，建议团队成员根据自身职责深入研究相关部分，确保技术实施的准确性和效率。</li></ul>',13)])])}const u=e(r,[["render",o]]);export{d as __pageData,u as default};
